/**
 * @param {number} n
 * @param {number} t
 * @return {number}
 */
var smallestNumber = function(n, t) {
    let prod = 1;
    let num = n;

    while (num > 0) {
        prod *= num % 10;
        num = Math.floor(num / 10);
    }

    if (prod % t === 0) {
        return n;
    }

    let rem = n % 10;
    prod /= rem;

    for (let i = 1; i <= 10; i++) {
        const newProd = prod * (rem + i);
        if (newProd % t === 0) {
            return n + i;
        }
    }

    return smallestNumber(n + 11, t);
};

/**
