var smallestNumber = function(n, t) {
    let prod = 1;
    let num = n;

    while (num > 0) {
        prod *= num % 10;
        num = Math.floor(num / 10);
    }

    if (prod % t === 0) {
        return n;
    }

    return smallestNumber(n + 1, t);
};
